func newEDITransfer() unsafe.Pointer { return unsafe.Pointer(new(editransfer.EDITransfer)) }

func newNEDITransfer(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]editransfer.EDITransfer, n)))
}

func ptrEDITransfer(p unsafe.Pointer, c int32) any {
	r := (*editransfer.EDITransfer)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.SourceOrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.SourceBusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.TargetOrganizationID))
	case 4:
		return (*string)(unsafe.Pointer(&r.TargetBusinessUnitID))
	case 5:
		return (*string)(unsafe.Pointer(&r.SourcePartnerID))
	case 6:
		return (*string)(unsafe.Pointer(&r.TargetPartnerID))
	case 7:
		return (*string)(unsafe.Pointer(&r.SourceShipmentID))
	case 8:
		return (*string)(unsafe.Pointer(&r.TargetShipmentID))
	case 9:
		return (*string)(unsafe.Pointer(&r.InboundMessageID))
	case 10:
		return (*string)(unsafe.Pointer(&r.Status))
	case 11:
		return &r.TenderPayload
	case 12:
		return &r.MappingSnapshot
	case 13:
		return &r.RejectionReason
	case 14:
		return &r.FailureReason
	case 15:
		return &r.ApprovalWorkflowID
	case 16:
		return &r.ApprovalWorkflowRunID
	case 17:
		return (*string)(unsafe.Pointer(&r.SubmittedByID))
	case 18:
		return &r.SubmittedAt
	case 19:
		return (*string)(unsafe.Pointer(&r.ApprovedByID))
	case 20:
		return &r.ApprovedAt
	case 21:
		return &r.ProcessingStartedAt
	case 22:
		return &r.ProcessedAt
	case 23:
		return (*string)(unsafe.Pointer(&r.RejectedByID))
	case 24:
		return &r.RejectedAt
	case 25:
		return (*string)(unsafe.Pointer(&r.CanceledByID))
	case 26:
		return &r.CanceledAt
	case 27:
		return &r.Version
	case 28:
		return &r.CreatedAt
	case 29:
		return &r.UpdatedAt
	}
	return nil
}

func valueEDITransfer(p unsafe.Pointer, c int32) any {
	r := (*editransfer.EDITransfer)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.SourceOrganizationID)
	case 2:
		return string(r.SourceBusinessUnitID)
	case 3:
		return string(r.TargetOrganizationID)
	case 4:
		return string(r.TargetBusinessUnitID)
	case 5:
		return string(r.SourcePartnerID)
	case 6:
		return string(r.TargetPartnerID)
	case 7:
		if r.SourceShipmentID == "" {
			return nil
		}
		return string(r.SourceShipmentID)
	case 8:
		if r.TargetShipmentID == "" {
			return nil
		}
		return string(r.TargetShipmentID)
	case 9:
		if r.InboundMessageID == "" {
			return nil
		}
		return string(r.InboundMessageID)
	case 10:
		return string(r.Status)
	case 11:
		return r.TenderPayload
	case 12:
		if r.MappingSnapshot == nil {
			return keel.EmptyJSONArray
		}
		return r.MappingSnapshot
	case 13:
		if r.RejectionReason == "" {
			return nil
		}
		return r.RejectionReason
	case 14:
		if r.FailureReason == "" {
			return nil
		}
		return r.FailureReason
	case 15:
		if r.ApprovalWorkflowID == "" {
			return nil
		}
		return r.ApprovalWorkflowID
	case 16:
		if r.ApprovalWorkflowRunID == "" {
			return nil
		}
		return r.ApprovalWorkflowRunID
	case 17:
		if r.SubmittedByID == "" {
			return nil
		}
		return string(r.SubmittedByID)
	case 18:
		return r.SubmittedAt
	case 19:
		if r.ApprovedByID == "" {
			return nil
		}
		return string(r.ApprovedByID)
	case 20:
		if r.ApprovedAt == nil {
			return nil
		}
		return *r.ApprovedAt
	case 21:
		if r.ProcessingStartedAt == nil {
			return nil
		}
		return *r.ProcessingStartedAt
	case 22:
		if r.ProcessedAt == nil {
			return nil
		}
		return *r.ProcessedAt
	case 23:
		if r.RejectedByID == "" {
			return nil
		}
		return string(r.RejectedByID)
	case 24:
		if r.RejectedAt == nil {
			return nil
		}
		return *r.RejectedAt
	case 25:
		if r.CanceledByID == "" {
			return nil
		}
		return string(r.CanceledByID)
	case 26:
		if r.CanceledAt == nil {
			return nil
		}
		return *r.CanceledAt
	case 27:
		return r.Version
	case 28:
		return r.CreatedAt
	case 29:
		return r.UpdatedAt
	}
	return nil
}

func attachEDITransfer(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*editransfer.EDITransfer)(p)
	switch rel {
	case 0:
		r.SourcePartner = (*edi.EDIPartner)(child)
	case 1:
		r.TargetPartner = (*edi.EDIPartner)(child)
	}
}

